<script setup lang="ts">
import { ref } from 'vue'
import type { PerformanceLevel } from '@englishflow/performance'
export interface MobileVocabularyCard { id: string; snapshotId: number | null; snapshotItemId: number | null; itemType: 'VOCAB' | 'CHUNK' | 'EXPRESSION'; itemId: number; title: string; phonetic: string | null; hint: string | null; meaningCn: string | null; definitionEn: string | null; examples: string[]; masteryStatus: string | null; dueLocalDate: string | null }
type Phase = 'FRONT' | 'REVEALING' | 'BACK' | 'SUBMITTING' | 'PENDING_SYNC' | 'ERROR'
const props = defineProps<{ card: MobileVocabularyCard; phase: Phase; performanceLevel: PerformanceLevel }>()
const emit = defineEmits<{ reveal: []; rate: [quality: 0 | 1 | 2 | 3] }>()
const qualityOptions = [{ value: 0 as const, label: '忘了' }, { value: 1 as const, label: '模糊' }, { value: 2 as const, label: '记得' }, { value: 3 as const, label: '很熟' }]
const selected = ref<number | null>(null)
function rate(value: 0 | 1 | 2 | 3): void { if (props.phase === 'BACK') { selected.value = value; emit('rate', value) } }
</script>
<template><view class="vocab-card" :class="{ 'vocab-card--static': performanceLevel === 'Performance' }"><view class="card-meta"><text>服务端词卡</text><text v-if="card.masteryStatus">{{ card.masteryStatus }}</text></view><view v-if="phase === 'FRONT' || phase === 'REVEALING'" class="card-front"><text class="eyebrow">先回忆，再揭晓</text><text class="word">{{ card.title }}</text><text v-if="card.phonetic" class="phonetic">{{ card.phonetic }}</text><text v-if="card.hint" class="hint">{{ card.hint }}</text><text class="privacy">正面不展示释义、例句或标准答案。</text><button tabindex="0" role="button" class="primary-button" type="button" :disabled="phase !== 'FRONT'" @click="emit('reveal')">{{ phase === 'REVEALING' ? '正在读取…' : '显示答案' }}</button></view><view v-else-if="phase === 'BACK' || phase === 'SUBMITTING' || phase === 'PENDING_SYNC'" class="card-back"><text class="eyebrow">主动回忆反馈</text><text class="word word--small">{{ card.title }}</text><text class="meaning">{{ card.meaningCn ?? '服务端未返回中文释义' }}</text><text v-if="card.definitionEn" class="definition">{{ card.definitionEn }}</text><view v-if="card.examples.length" class="examples"><text v-for="example in card.examples" :key="example">{{ example }}</text></view><text v-if="card.dueLocalDate" class="hint">下次复习：{{ card.dueLocalDate }}</text><view class="ratings"><button tabindex="0" role="button" v-for="option in qualityOptions" :key="option.value" class="rating" :class="{ 'rating--selected': selected === option.value }" type="button" :disabled="phase !== 'BACK'" @click="rate(option.value)">{{ option.value }} · {{ option.label }}</button></view><text v-if="phase === 'PENDING_SYNC'" class="notice">已排队待同步，服务端尚未确认掌握变化。</text></view><view v-else class="card-error"><text class="word word--small">这张卡片暂时无法继续</text><text class="hint">没有伪造答案或掌握结果，请刷新服务端批次。</text></view></view></template>
<style scoped lang="scss">.vocab-card{padding:32rpx 24rpx;border:1rpx solid var(--yx-border);border-radius:24rpx;background:var(--yx-surface-card);box-shadow:0 12rpx 34rpx var(--yx-border)}.vocab-card--static{box-shadow:none}.card-meta{display:flex;justify-content:space-between;color:var(--yx-text-tertiary);font-size:22rpx}.card-front,.card-back,.card-error{display:grid;gap:22rpx;align-content:center;min-height:700rpx;text-align:center}.eyebrow{color:var(--yx-brand);font-size:21rpx;font-weight:700;letter-spacing:2rpx}.word{font-size:84rpx;font-weight:800;line-height:1.1}.word--small{font-size:52rpx}.phonetic,.hint,.definition,.privacy{color:var(--yx-text-secondary);font-size:24rpx;line-height:1.6}.privacy{color:var(--yx-text-tertiary);font-size:21rpx}.meaning{font-size:42rpx;font-weight:750}.primary-button{min-height:88rpx;border:0;border-radius:16rpx;color:var(--yx-on-brand);background:var(--yx-action);font-size:28rpx;font-weight:700}.ratings{display:grid;grid-template-columns:repeat(2,1fr);gap:12rpx}.rating{min-height:88rpx;border:1rpx solid var(--yx-border);border-radius:14rpx;color:var(--yx-text-primary);background:var(--yx-surface-card);font-size:24rpx}.rating--selected{border-color:var(--yx-brand);color:var(--yx-brand);background:var(--yx-brand-soft)}.rating:disabled{opacity:.6}.examples{display:grid;gap:12rpx;padding:18rpx;border-radius:14rpx;background:var(--yx-surface-page);text-align:left}.examples text{color:var(--yx-text-secondary);font-size:23rpx;line-height:1.6}.notice{padding:16rpx;border-radius:12rpx;color:var(--yx-warning);background:var(--yx-danger-soft);font-size:22rpx}</style>
